// File: contracts/LONGD.sol


pragma solidity ^0.8.19;



contract LONGD is ERC20, Ownable {
    uint256 public constant INITIAL_SUPPLY = 1000000000000000000000000 * 10**18; // 1 Billion Tokens

    constructor() ERC20("LONGD", "LONGD") Ownable(msg.sender) {
        _mint(msg.sender, INITIAL_SUPPLY);
    }

    function mint(address to, uint256 amount) public onlyOwner {
        _mint(to, amount);
    }

    function burn(uint256 amount) public {
        _burn(msg.sender, amount);
    }
}

